"""Real JEE Main questions — Chemistry Unit 20: Principles Related to Practical Chemistry (detection of elements,
salt analysis, titrations, preparation of inorganic/organic compounds). Our own solutions; chk recomputes
numbers (Ksp → precipitation pH/order, titration concentrations) by code and checks test outcomes against tables
of group reagents, flame colours and confirmatory tests written from NCERT lab manuals."""
import math
from common import new_registry, pick, verify
from chemkit import stmt, pickset
P, add = new_registry()
GROUP = {'Pb2+': 1, 'Ag+': 1, 'Cu2+': 2, 'Cd2+': 2, 'As3+': 2, 'Al3+': 3, 'Fe3+': 3, 'Cr3+': 3, 'Zn2+': 4, 'Ni2+': 4, 'Co2+': 4, 'Mn2+': 4, 'Ba2+': 5, 'Ca2+': 5, 'Sr2+': 5, 'Mg2+': 6, 'NH4+': 0, 'Na+': 6, 'K+': 6}
GPPT = {1: 'chloride', 2: 'sulphide', 3: 'hydroxide', 4: 'sulphide', 5: 'carbonate'}
FLAME = {'Ca2+': 'brick red', 'Sr2+': 'crimson red', 'Ba2+': 'apple green', 'Cu2+': 'green-blue', 'Na+': 'golden yellow', 'K+': 'lilac'}
FERRO = {'Cu2+': 'chocolate brown ppt', 'Fe3+': 'Prussian blue ppt', 'Zn2+': 'bluish-white ppt'}     # K4[Fe(CN)6] identification tests
AGX = {'Cl-': ('white', 'readily soluble'), 'Br-': ('pale yellow', 'sparingly soluble'), 'I-': ('yellow', 'insoluble')}
UNP = {'Cr2+': 4, 'Fe2+': 4, 'Fe3+': 5, 'Zn2+': 0}
STC = ['Statement I is correct but Statement II is incorrect', 'Both Statement I and Statement II are incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are correct']

# ---------------- salt analysis: cations ----------------
add(('2026', 'Jan', '2026-01-24', 2), 'cat', 'In the Group analysis of cations, Ba^{2+} & Ca^{2+} are precipitated respectively as', ['sulphide & sulphide', 'hydroxide & carbonate', 'carbonate & carbonate', 'chromate & sulphide'], 3,
    lambda: pick(['sulphide & sulphide', 'hydroxide & carbonate', 'carbonate & carbonate', 'chromate & sulphide'], GPPT[GROUP['Ba2+']] + ' & ' + GPPT[GROUP['Ca2+']]), ['Ba^{2+}, Sr^{2+}, Ca^{2+} form group V: precipitated by (NH_{4})_{2}CO_{3} in presence of NH_{4}Cl/NH_{4}OH as BaCO_{3} and CaCO_{3}.'], 'cat', 1)
add(('2024', 'Apr', '2024-04-04', 1), 'cat', 'In the precipitation of the iron group (III) in qualitative analysis, ammonium chloride is added before adding ammonium hydroxide to :', ['prevent interference by phosphate ions', 'decrease concentration of ^{−}OH ions', 'increase concentration of Cl^{−} ions', 'increase concentration of NH_{4}^{+} ions'], 2,
    lambda: pick([False, True, False, False], True), ['Common-ion effect: NH_{4}^{+} from NH_{4}Cl suppresses NH_{4}OH ⇌ NH_{4}^{+} + OH^{−}.', 'The lowered [OH^{−}] exceeds K_{sp} only for the very insoluble Fe(OH)_{3}, Al(OH)_{3}, Cr(OH)_{3}; group IV–VI hydroxides (Zn, Mn, Mg) stay in solution.'], 'cat', 1)
add(('2025', 'Apr', '2025-04-02', 1), 'cat', 'Choose the correct tests with respective observations. (A) CuSO_{4} (acidified with acetic acid) + K_{4}[Fe(CN)_{6}] → Chocolate brown precipitate. (B) FeCl_{3} + K_{4}[Fe(CN)_{6}] → Prussian blue precipitate. (C) ZnCl_{2} + K_{4}[Fe(CN)_{6}], neutralised with NH_{4}OH → White or bluish white precipitate. (D) MgCl_{2} + K_{4}[Fe(CN)_{6}] → Blue precipitate. (E) BaCl_{2} + K_{4}[Fe(CN)_{6}], neutralised with NaOH → White precipitate.',
    ['B, D and E only', 'C, D and E only', 'A, B and C only', 'A, D and E only'], 3,
    lambda: pickset(['B, D and E only', 'C, D and E only', 'A, B and C only', 'A, D and E only'], {k: c in FERRO for k, c in zip('ABCDE', ('Cu2+', 'Fe3+', 'Zn2+', 'Mg2+', 'Ba2+'))}),
    ['Ferrocyanide identifies Cu^{2+} (Cu_{2}[Fe(CN)_{6}], chocolate brown), Fe^{3+} (Fe_{4}[Fe(CN)_{6}]_{3}, Prussian blue) and Zn^{2+} (bluish-white).', 'Mg^{2+} and Ba^{2+} give no such characteristic precipitate.'], 'cat', 1)
add(('2025', 'Jan', '2025-01-24', 1), 'cat', 'Among the following cations, the number of cations which will give characteristic precipitate in their identification tests with K_{4}[Fe(CN)_{6}] is ______: Cu^{2+}, Fe^{3+}, Ba^{2+}, Ca^{2+}, NH_{4}^{+}, Mg^{2+}, Zn^{2+}', None, 3,
    lambda: sum(c in FERRO for c in ('Cu2+', 'Fe3+', 'Ba2+', 'Ca2+', 'NH4+', 'Mg2+', 'Zn2+')), ['Cu^{2+} chocolate brown, Fe^{3+} Prussian blue, Zn^{2+} bluish white → 3.'], 'cat', 1)
add(('2024', 'Jan', '2024-01-30', 2), 'cat', 'Number of metal ions characterized by flame test among the following is _____: Sr^{2+}, Ba^{2+}, Ca^{2+}, Cu^{2+}, Zn^{2+}, Co^{2+}, Fe^{2+}', None, 4,
    lambda: sum(c in FLAME for c in ('Sr2+', 'Ba2+', 'Ca2+', 'Cu2+', 'Zn2+', 'Co2+', 'Fe2+')), ['Flame colours: Sr crimson, Ba apple green, Ca brick red, Cu green-blue.', 'Zn, Co, Fe give no characteristic flame → 4.'], 'cat', 1)
add(('2026', 'Apr', '2026-04-02', 1), 'cat', 'A salt with few drops of conc. HCl gives apple green colour in flame test. The group precipitate of the salt is dissolved in acetic acid and treated with K_{2}CrO_{4} to give yellow precipitate. When the sodium carbonate extract of the salt solution is heated with conc. HNO_{3} and ammonium molybdate, it resulted a canary yellow precipitate. The cation and anion present in the salt are respectively,',
    ['Ca^{2+} and SO_{4}^{2−}', 'Ba^{2+} and PO_{4}^{3−}', 'Mn^{2+} and PO_{4}^{3−}', 'Ba^{2+} and SO_{4}^{2−}'], 2,
    lambda: pick([('Ca2+', 'SO4'), ('Ba2+', 'PO4'), ('Mn2+', 'PO4'), ('Ba2+', 'SO4')], (next(c for c, f in FLAME.items() if f == 'apple green'), 'PO4')),
    ['Apple-green flame and yellow BaCrO_{4} with K_{2}CrO_{4} → Ba^{2+}.', 'Canary-yellow ammonium phosphomolybdate with HNO_{3}/(NH_{4})_{2}MoO_{4} → PO_{4}^{3−}.'], 'cat', 1)
add(('2024', 'Jan', '2024-01-29', 2), 'cat', 'A reagent which gives brilliant red precipitate with Nickel ions in basic medium is', ['sodium nitroprusside', 'neutral FeCl_{3}', 'meta-dinitrobenzene', 'dimethyl glyoxime'], 4,
    lambda: pick(['nitroprusside', 'FeCl3', 'm-DNB', 'dmg'], 'dmg'), ['Ni^{2+} + 2 dmgH in NH_{4}OH → [Ni(dmgH)_{2}], a rose-red chelate (confirmatory test for group IV Ni^{2+}).'], 'cat', 1)
add(('2026', 'Apr', '2026-04-02', 2), 'cat', 'Among Fe^{2+}, Fe^{3+}, Cr^{2+} and Zn^{2+}, the ion that shows positive borax bead test and with highest ionisation enthalpy is :', ['Fe^{2+}', 'Zn^{2+}', 'Cr^{2+}', 'Fe^{3+}'], 4,
    lambda: pick(['Fe2+', 'Zn2+', 'Cr2+', 'Fe3+'], max((c for c, u in UNP.items() if u > 0), key=lambda c: (int(c[-2]), UNP[c]))),
    ['Borax beads need a coloured (d-electron) ion: Zn^{2+} (d^{10}) gives a colourless bead and is out.', 'Removing a further electron from the higher-charged Fe^{3+} (stable half-filled d^{5}) costs the most energy → Fe^{3+}.'], 'cat', 2)
add(('2025', 'Jan', '2025-01-23', 1), 'cat', 'Which of the following happens when NH_{4}OH is added gradually to the solution containing 1 M A^{2+} and 1 M B^{3+} ions? Given : K_{sp}[A(OH)_{2}] = 9 × 10^{−10} and K_{sp}[B(OH)_{3}] = 27 × 10^{−18} at 298 K.',
    ['A(OH)_{2} will precipitate before B(OH)_{3}', 'Both A(OH)_{2} and B(OH)_{3} do not show precipitation with NH_{4}OH', 'A(OH)_{2} and B(OH)_{3} will precipitate together', 'B(OH)_{3} will precipitate before A(OH)_{2}'], 4,
    lambda: pick(['A', 'none', 'same', 'B'], 'B' if (27e-18) ** (1 / 3) < math.sqrt(9e-10) else 'A'),
    ['[OH^{−}] needed: A(OH)_{2}: √(9 × 10^{−10}/1) = 3 × 10^{−5} M; B(OH)_{3}: ∛(27 × 10^{−18}/1) = 3 × 10^{−6} M.', 'B(OH)_{3} needs less OH^{−} → it precipitates first (like Fe(OH)_{3} in group III).'], 'cat', 2)
add(('2024', 'Jan', '2024-01-30', 1), 'cat', 'The pH at which Mg(OH)_{2} [K_{sp} = 1 × 10^{−11}] begins to precipitate from a solution containing 0.10 M Mg^{2+} ions is ______', None, 9,
    lambda: round(14 + math.log10(math.sqrt(1e-11 / 0.10))), ['[OH^{−}] = √(K_{sp}/[Mg^{2+}]) = √(10^{−10}) = 10^{−5} M.', 'pOH 5 → pH 9.'], 'cat', 1)
add(('2024', 'Jan', '2024-01-27', 1), 'cat', 'Yellow compound of lead chromate gets dissolved on treatment with hot NaOH solution. The product of lead formed is a :', ['Tetraanionic complex with coordination number six', 'Neutral complex with coordination number four', 'Dianionic complex with coordination number six', 'Dianionic complex with coordination number four'], 4,
    lambda: pick([(-4, 6), (0, 4), (-2, 6), (-2, 4)], (2 - 4, 4)), ['PbCrO_{4} + 4OH^{−} → [Pb(OH)_{4}]^{2−} + CrO_{4}^{2−} (confirms Pb^{2+} in group I/II analysis).', 'Charge +2 − 4 = −2 (dianion), four OH^{−} ligands → CN 4.'], 'cat', 2)

# ---------------- anions, gases, detection of elements ----------------
add(('2024', 'Apr', '2024-04-06', 2), 'ani', 'During the detection of acidic radical present in a salt, a student gets a pale yellow precipitate soluble with difficulty in NH_{4}OH solution when sodium carbonate extract was first acidified with dil. HNO_{3} and then AgNO_{3} solution was added. This indicates presence of:', ['Br^{−}', 'CO_{3}^{2−}', 'I^{−}', 'Cl^{−}'], 1,
    lambda: pick(['Br-', 'CO3', 'I-', 'Cl-'], next(k for k, v in AGX.items() if v == ('pale yellow', 'sparingly soluble'))), ['AgCl white, readily soluble in NH_{4}OH; AgBr pale yellow, sparingly soluble; AgI yellow, insoluble.', 'So the radical is Br^{−}.'], 'ani', 1)
add(('2024', 'Jan', '2024-01-30', 1), 'ani', 'Given below are two statements: Statement-I: The gas liberated on warming a salt with dil H_{2}SO_{4}, turns a piece of paper dipped in lead acetate into black, it is a confirmatory test for sulphide ion. Statement-II: In statement-I the colour of paper turns black because of formation of lead sulphite. In the light of the above statements, choose the most appropriate answer from the options given below:',
    ['Both Statement-I and Statement-II are false', 'Statement-I is false but Statement-II is true', 'Statement-I is true but Statement-II is false', 'Both Statement-I and Statement-II are true.'], 3,
    lambda: stmt(True, False, ['Both Statement I and Statement II are false', 'Statement I is false but Statement II is true', 'Statement I is true but Statement II is false', 'Both Statement I and Statement II are true.']),
    ['S^{2−} + H_{2}SO_{4} → H_{2}S, which blackens lead acetate paper. I true.', 'The black solid is lead SULPHIDE (PbS), not sulphite. II false.'], 'ani', 1)
add(('2025', 'Apr', '2025-04-07', 1), 'ani', 'When a salt is treated with sodium hydroxide solution it gives gas X. On passing gas X through reagent Y a brown coloured precipitate is formed. X and Y respectively, are', ['X = NH_{3} and Y = K_{2}HgI_{4} + KOH', 'X = HCl and Y = NH_{4}Cl', 'X = NH_{3} and Y = HgO', 'X = NH_{4}Cl and Y = KOH'], 1,
    lambda: pick([('NH3', 'Nessler'), ('HCl', 'NH4Cl'), ('NH3', 'HgO'), ('NH4Cl', 'KOH')], ('NH3', 'Nessler')), ['NH_{4}^{+} + OH^{−} → NH_{3}↑ on warming.', 'Nessler\'s reagent (K_{2}HgI_{4} in KOH) + NH_{3} → brown basic mercury(II) amido-iodide (iodide of Millon\'s base).'], 'ani', 1)
add(('2024', 'Jan', '2024-01-29', 2), 'ani', "On passing a gas, 'X', through Nessler's reagent, a brown precipitate is obtained. The gas 'X' is", ['H_{2}S', 'CO_{2}', 'NH_{3}', 'Cl_{2}'], 3,
    lambda: pick(['H2S', 'CO2', 'NH3', 'Cl2'], 'NH3'), ['Nessler\'s reagent is the specific test for ammonia/ammonium: brown precipitate.'], 'ani', 1)
add(('2026', 'Jan', '2026-01-22', 1), 'ani', "A 'p'-block element (E) and hydrogen form a binary cation (EH_{x})^{+}, while EH_{3} on treatment with K_{2}HgI_{4} in alkaline medium gives a precipitate of basic mercury(II) amido-iodine. Given below are first ionisation enthalpy values (kJ mol^{−1}) for first element each from group 13, 14, 15 and 16. Identify the correct first ionisation enthalpy value for element E.", ['1312', '1086', '1402', '801'], 3,
    lambda: pick([1312, 1086, 1402, 801], {'B': 801, 'C': 1086, 'N': 1402, 'O': 1314}['N']), ['Nessler\'s test → EH_{3} = NH_{3}, E = N (NH_{4}^{+} is the cation).', 'First IE: B 801, C 1086, N 1402, O 1314 → 1402 (N exceeds O: half-filled 2p^{3}).'], 'ani', 2)
add(('2024', 'Feb', '2024-02-01', 2), 'ani', "Lassaigne's test is used for detection of :", ['Nitrogen and Sulphur only', 'Nitrogen, Sulphur and Phosphorous Only', 'Phosphorous and halogens only', 'Nitrogen, Sulphur, phosphorous and halogens'], 4,
    lambda: pick([{'N', 'S'}, {'N', 'S', 'P'}, {'P', 'X'}, {'N', 'S', 'P', 'X'}], {'N', 'S', 'P', 'X'}), ['Fusion with Na converts N → NaCN, S → Na_{2}S, X → NaX, and P (with Na_{2}O_{2} fusion) → phosphate, all tested in the extract.', 'So the sodium-fusion (Lassaigne) extract is used for N, S, P and halogens.'], 'ani', 1)
add(('2024', 'Apr', '2024-04-08', 2), 'ani', 'In qualitative test for identification of presence of phosphorous, the compound is heated with an oxidising agent. Which is further treated with nitric acid and ammonium molybdate respectively. The yellow coloured precipitate obtained is :', ['Na_{3}PO_{4}·12MoO_{3}', '(NH_{4})_{3}PO_{4}·12(NH_{4})_{2}MoO_{4}', '(NH_{4})_{3}PO_{4}·12MoO_{3}', 'MoPO_{4}·21NH_{4}NO_{3}'], 3,
    lambda: pick(['Na3PO4.12MoO3', '(NH4)3PO4.12(NH4)2MoO4', '(NH4)3PO4.12MoO3', 'MoPO4.21NH4NO3'], '(NH4)3PO4.12MoO3'), ['P is oxidised (Na_{2}O_{2}) to PO_{4}^{3−}.', 'H_{3}PO_{4} + 12(NH_{4})_{2}MoO_{4} + 21HNO_{3} → (NH_{4})_{3}PO_{4}·12MoO_{3} (canary yellow, ammonium phosphomolybdate) + 21NH_{4}NO_{3} + 12H_{2}O.'], 'ani', 1)

# ---------------- titrations & preparations ----------------
add(('2025', 'Jan', '2025-01-28', 1), 'titr', 'Given below are two statements: Statement I: In the oxalic acid vs KMnO_{4} (in the presence of dil H_{2}SO_{4}) titration the solution needs to be heated initially to 60 °C, but no heating is required in Ferrous ammonium sulphate (FAS) vs KMnO_{4} titration (in the presence of dil H_{2}SO_{4}). Statement II: In oxalic acid vs KMnO_{4} titration, the initial formation of MnSO_{4} takes place at high temperature, which then acts as catalyst for further reaction. In the case of FAS vs KMnO_{4}, heating oxidizes Fe^{2+} into Fe^{3+} by oxygen of air and error may be introduced in the experiment. In the light of the above statements, choose the correct answer from the options given below',
    ['Both Statement I and Statement II are false', 'Both Statement I and Statement II are true', 'Statement I is false but Statement II is true', 'Statement I is true but Statement II is false'], 2,
    lambda: stmt(True, True, ['Both Statement I and Statement II are false', 'Both Statement I and Statement II are true', 'Statement I is false but Statement II is true', 'Statement I is true but Statement II is false']),
    ['Oxalate reacts slowly with MnO_{4}^{−} until some Mn^{2+} forms (autocatalysis), so the flask is warmed to 50–60 °C. I true.', 'Fe^{2+} reacts fast at room temperature, and warming would let air oxidise Fe^{2+} → Fe^{3+}, causing error. II true.'], 'titr', 1)
add(('2024', 'Apr', '2024-04-05', 2), 'titr', "While preparing crystals of Mohr's salt, dil. H_{2}SO_{4} is added to a mixture of ferrous sulphate and ammonium sulphate, before dissolving this mixture in water, dil. H_{2}SO_{4} is added here to :", ['prevent the hydrolysis of ferrous sulphate', 'prevent the hydrolysis of ammonium sulphate', 'make the medium strongly acidic', 'increase the rate of formation of crystals'], 1,
    lambda: pick([True, False, False, False], True), ['Fe^{2+} hydrolyses (and then oxidises) in water: Fe^{2+} + 2H_{2}O ⇌ Fe(OH)_{2} + 2H^{+}.', 'A little dil. H_{2}SO_{4} pushes this back, keeping a clear pale-green solution of FeSO_{4}·(NH_{4})_{2}SO_{4}·6H_{2}O.'], 'titr', 1)
add(('2025', 'Apr', '2025-04-03', 2), 'titr', '40 mL of a mixture of CH_{3}COOH and HCl (aqueous solution) is titrated against 0.1 M NaOH solution conductometrically. The conductance falls steeply from A to the first break B at 2.0 mL of NaOH, then rises slowly to the second break C at 5.0 mL, then rises steeply to D. Which of the following statement is correct?',
    ['CH_{3}COOH is neutralised first followed by neutralisation of HCl', 'The concentration of CH_{3}COOH in the original mixture is 0.005 M', "Point 'C' indicates the complete neutralization of HCl", 'The concentration of HCl in the original mixture is 0.005 M'], 4,
    lambda: pick([False, abs(0.1 * 3.0 / 40 - 0.005) < 1e-9, False, abs(0.1 * 2.0 / 40 - 0.005) < 1e-9], True),
    ['Strong HCl is neutralised first: fast H^{+} replaced by Na^{+} → steep fall to B (2.0 mL). [HCl] = 0.1 × 2.0/40 = 0.005 M.', 'B → C neutralises CH_{3}COOH (3.0 mL → 0.0075 M); after C excess NaOH raises conductance sharply.'], 'titr', 2)

for _p in P: _p['t'] = _p['fam']
